  const now = Date.now();
  const map = this.viewers.get(sid);
  if (!map) return [];
  const out: string[] = [];
  map.forEach((seen, name) => {
    if (now - seen > 60_000) map.delete(name);
    else out.push(name);
  });
  if (!map.size) this.viewers.delete(sid);
  return out.sort().slice(0, 20);
}

