/** Bootstrap from file text. Split by UTF-16 unit to match textarea offsets
 * (an emoji counts 2, exactly like selectionStart). */
export function docFromText(site: string, text: string): CrdtDoc {
  const doc = emptyDoc(site);
  let prev: number[] | null = null;
  for (const ch of String(text ?? "").split("")) {
    const pos = posBetween(prev, null);
    doc.chars.push({ pos, site, ch, dead: false });
    prev = pos;
  }
  return doc;
}

